cat > /testbed/test_entity_decoding.js << 'EOF'
const { Window } = require('./packages/happy-dom/lib/index.js');

const window = new Window();
const document = window.document;

console.log('Testing HTML entity decoding in textContent...\n');

let passed = 0;
let failed = 0;

function test(name, actual, expected) {
    if (actual === expected) {
        console.log(`✓ ${name}`);
        passed++;
    } else {
        console.log(`✗ ${name}`);
        console.log(`  Expected: ${JSON.stringify(expected)}`);
        console.log(`  Actual:   ${JSON.stringify(actual)}`);
        failed++;
    }
}

// Test basic HTML entities
document.documentElement.innerHTML = '<div id="test">&gt;howdy</div>';
test('&gt; decoding', document.getElementById('test').textContent, '>howdy');

document.documentElement.innerHTML = '<div id="test">&lt;hello</div>';
test('&lt; decoding', document.getElementById('test').textContent, '<hello');

document.documentElement.innerHTML = '<div id="test">&amp;world</div>';
test('&amp; decoding', document.getElementById('test').textContent, '&world');

document.documentElement.innerHTML = '<div id="test">&quot;quoted&quot;</div>';
test('&quot; decoding', document.getElementById('test').textContent, '"quoted"');

document.documentElement.innerHTML = '<div id="test">&apos;apostrophe&apos;</div>';
test('&apos; decoding', document.getElementById('test').textContent, "'apostrophe'");

// Test multiple entities
document.documentElement.innerHTML = '<div id="test">&lt;&gt;&amp;</div>';
test('Multiple entities', document.getElementById('test').textContent, '<>&');

// Test numeric character references
document.documentElement.innerHTML = '<div id="test">&#62;decimal</div>';
test('Decimal numeric reference', document.getElementById('test').textContent, '>decimal');

document.documentElement.innerHTML = '<div id="test">&#x3E;hex</div>';
test('Hex numeric reference', document.getElementById('test').textContent, '>hex');

// Test named entities
document.documentElement.innerHTML = '<div id="test">&nbsp;space</div>';
test('Named entity &nbsp;', document.getElementById('test').textContent, '\u00a0space');

document.documentElement.innerHTML = '<div id="test">&copy;copyright</div>';
test('Named entity &copy;', document.getElementById('test').textContent, '©copyright');

// Test that script tags don't decode (plain text elements)
document.documentElement.innerHTML = '<script id="test">if (a &gt; b)</script>';
test('Script tag no decode', document.getElementById('test').textContent, 'if (a &gt; b)');

// Test that style tags don't decode (plain text elements)
document.documentElement.innerHTML = '<style id="test">.class &gt; .child</style>';
test('Style tag no decode', document.getElementById('test').textContent, '.class &gt; .child');

// Test nested elements with entities
document.documentElement.innerHTML = '<div id="test"><span>&lt;</span><p>&gt;</p></div>';
test('Nested elements', document.getElementById('test').textContent, '<>');

// Test mixed content
document.documentElement.innerHTML = '<div id="test">Hello &amp; welcome to &lt;world&gt;</div>';
test('Mixed content', document.getElementById('test').textContent, 'Hello & welcome to <world>');

// Test attribute values are also decoded
document.documentElement.innerHTML = '<div id="test" title="&lt;test&gt;"></div>';
test('Attribute value', document.getElementById('test').getAttribute('title'), '<test>');

console.log(`\n${passed} passed, ${failed} failed`);
process.exit(failed > 0 ? 1 : 0);
EOF
